// 作者、身份、新尾和真实回执严格同启；原首任继位档不因存在原政策字符串自动启用本功能。
#include "political_successor_round_profile.hpp"
#include "resident/domains/politics/succession/political_succession_profile.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
namespace hanmo::resident {
// 精确五类来源，不按political前缀或domain宽放。
bool is_political_successor_round_fact_kind(const StableId& k){return k=="political_successor_round_nominated"||k=="political_successor_round_accepted"||k=="political_successor_round_declined"||k=="political_successor_round_withdrawn"||k=="political_successor_round_acceded";}
// 新尾显式版本与原首轮依赖同启，重复与未知版本拒绝。
Outcome<Integer> political_successor_round_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){Integer count=0;for(const auto& m:modules)if(m.first==political_successor_rounds_domain){if(m.second!="1"||++count!=1)return {false,0,common_failure("PoliticalSuccessorRoundModuleMismatch").error};}if(!count)return {true,0,{}};auto original=political_succession_selected_version(modules);if(!original.ok)return original;if(original.value!=1)return {false,0,common_failure("PoliticalSuccessorRoundOriginalProfileRequired").error};return {true,1,{}};}
// 必须作者同时声明两份独立政策，不能由旧提名或原控制换人推导新轮提名条款。
Outcome<std::optional<PoliticalSuccessorRoundCatalog>> decode_political_successor_round_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){const auto* dynamic=scenario.find("dynamic_world");const auto* group=dynamic?dynamic->find(political_successor_rounds_domain):nullptr;if(!group)return {true,std::nullopt,{}};if(std::find(caps.begin(),caps.end(),"political_successor_rounds_v1")==caps.end())return {false,{},common_failure("PoliticalSuccessorRoundCapabilityRequired").error};auto original=decode_political_succession_profile(scenario,caps);if(!original.ok)return {false,{},original.error};if(!original.value)return {false,{},common_failure("PoliticalSuccessorRoundOriginalProfileRequired").error};auto decoded=decode_political_successor_round_catalog(*group);if(!decoded.ok)return {false,{},decoded.error};if(decoded.value.policies.empty()||decoded.value.policies.size()>4096)return {false,{},common_failure("InvalidPoliticalSuccessorRoundCatalog").error};return {true,std::move(decoded.value),{}};}
// 未选择时连空账与缓存新命令也拒绝，旧档不追加空尾。
Status validate_political_successor_round_layout(const CommonStore& common,const std::vector<std::pair<StableId,StableId>>& modules,const PoliticalSuccessorRoundState* state){auto selected=political_successor_round_selected_version(modules);if(!selected.ok)return {false,{},selected.error};if(bool(state)!=(selected.value==1)||(state&&state->version!=1))return common_failure("PoliticalSuccessorRoundProfileMismatch");if(!state){for(const auto& row:common.state().facts.rows())if(is_political_successor_round_fact_kind(row.second.kind)||row.second.domain==political_successor_rounds_domain)return common_failure("PoliticalSuccessorRoundProfileRequired",row.first);for(const auto& h:common.state().history)if(is_political_successor_round_command(h.kind))return common_failure("PoliticalSuccessorRoundProfileRequired",h.result_id);for(const auto& row:common.state().results.rows())if(row.second&&is_political_successor_round_command(row.second->kind))return common_failure("PoliticalSuccessorRoundProfileRequired",row.first);}return common_success();}
// Common JSON只豁免恰一真实本账载荷，不用整个domain冒任意额外事实。
Status validate_political_successor_round_fact_header(const CommonStore& common,const PoliticalSuccessorRoundState& s,const FactRecord& h){auto n=political_successor_round_fact_sequence(common,h.id);const auto* a=s.nominations.find(h.id);const auto* b=s.answers.find(h.id);const auto* c=s.withdrawals.find(h.id);const auto* d=s.accessions.find(h.id);if(s.version!=1||!n||h.domain!=political_successor_rounds_domain||Integer(bool(a))+Integer(bool(b))+Integer(bool(c))+Integer(bool(d))!=1)return common_failure("PoliticalSuccessorRoundFactMismatch",h.id);const auto& id=a?a->id:b?b->id:c?c->id:d->id;const StableId kind=a?"political_successor_round_nominated":b?(b->accepted?"political_successor_round_accepted":"political_successor_round_declined"):c?"political_successor_round_withdrawn":"political_successor_round_acceded";return id==h.id&&h.kind==kind?common_success():common_failure("PoliticalSuccessorRoundFactMismatch",h.id);}
// 新轮接受仅是未来意愿，只有具名正式就任有一个原Office结果，其他三个命令不得夹带。
bool valid_political_successor_round_effect(const StableId& kind,const PoliticsEffects& e){if(!is_political_successor_round_command(kind)||!e.appointment_id.empty()||e.fact_ids.size()!=1)return false;const auto& id=e.fact_ids.front();if(kind==political_successor_round_nominate_command)return organization_instance_sequence(id,"political_successor_round_nomination").has_value()&&e.receipt_ids.empty();if(kind==political_successor_round_withdraw_command)return organization_instance_sequence(id,"political_successor_round_withdrawal").has_value()&&e.receipt_ids.empty();if(kind==political_successor_round_answer_command)return (organization_instance_sequence(id,"political_successor_round_acceptance")||organization_instance_sequence(id,"political_successor_round_decline"))&&e.receipt_ids.empty();return organization_instance_sequence(id,"political_successor_round_accession").has_value()&&e.receipt_ids.size()==1&&organization_instance_sequence(e.receipt_ids.front(),"organization").has_value();}
}
